import React, { useState, useCallback, useRef, useEffect } from 'react';
import ReactQuill, { Quill as Quills } from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import quillEmoji from 'quill-emoji';
import "quill-emoji/dist/quill-emoji.css"; //这个不引入的话会出现emoji框一直在输入框下面的情况
import './index.less';
//注册ToolbarEmoji，将在工具栏出现emoji；注册TextAreaEmoji，将在文本输入框处出现emoji。VideoBlot是我自定义的视频组件，后面会讲，
import { VideoBlot } from './VideoBlot';
import BlotFormatter from 'quill-blot-formatter';
import * as Quill from 'quill';
import ajax, { base64URLtoFile } from 'ajax';
import { Spin } from '@arco-design/web-react';
// const { Delta } = Quill

const { EmojiBlot, ShortNameEmoji, ToolbarEmoji, TextAreaEmoji } = quillEmoji;
Quills.register({
    'formats/emoji': EmojiBlot,
    'formats/video': VideoBlot,
    'modules/emoji-shortname': ShortNameEmoji,
    'modules/emoji-toolbar': ToolbarEmoji,
    'modules/emoji-textarea': TextAreaEmoji,
    'modules/blotFormatter': BlotFormatter,
    // 'modules/ImageExtend': ImageExtend, //拖拽图片扩展组件
    // 'modules/ImageDrop': ImageDrop, //复制粘贴组件
}, true);

export interface UnprivilegedEditor {
    getLength(): number;
    getText(index?: number, length?: number): string;
    getHTML(): string;
    getBounds(index: number, length?: number): Quill.BoundsStatic;
    getSelection(focus?: boolean): Quill.RangeStatic;
    getContents(index?: number, length?: number): Quill.DeltaStatic;
}


export interface EditorQuillProps{
    id?: string;
    className?: string;
    theme?: string;
    style?: React.CSSProperties;
    readOnly?: boolean;
    value?: string | Quill.Delta;
    defaultValue?: string | Quill.Delta;
    placeholder?: string;
    tabIndex?: number;
    bounds?: string | HTMLElement;
    scrollingContainer?: string | HTMLElement;
    onChange?: (
        content: string,
        delta: Quill.Delta,
        source: Quill.Sources,
        editor: UnprivilegedEditor
    ) => void;
}

const EditorQuill = (props: EditorQuillProps) => {
    
    const reactQuillRef: any = useRef();
    const [loading, setLoading] = useState<boolean>(false);
    const [file, setFile] = useState<any>({});

    // 批量上传图片列表
    const requestFile = (file: any) => {
        const formData = new FormData();
        setFile(file);
        setLoading(true);
        formData.append('image', file);
        return ajax.post(
            '/upload-img',
            formData,
        ).then((res) =>{
            return res.data.url
        }).finally(() => {
            setLoading(false)
        })
    }

    // 实现图片添加功能
    const imageHeader = useCallback(() => {
        const input: any = document.createElement('input')
        input.setAttribute('type', 'file')
        input.setAttribute('accept', 'image/*')
        input.setAttribute('multiple', 'multiple')
        input.click()
        input.onchange = async () => {
            for (const item of input.files) {
                await requestFile(item).then((url: any) => {
                    let quill = reactQuillRef.current.getEditor();//获取到编辑器本身
                    const cursorPosition = quill.getSelection().index;//获取当前光标位置
                    quill.insertEmbed(cursorPosition, "image", url);//插入图片
                    quill.setSelection(cursorPosition + 1);//光标位置加1
                });
            }
        }
    },[])


    useEffect(() => {

        console.log('reactQuillRef.current.editor', reactQuillRef.current)

        if(!reactQuillRef.current) return;
        
        reactQuillRef.current.editor.clipboard.addMatcher(Node.ELEMENT_NODE,function (node: any, delta: any) {
            // 当前粘贴内容是否存在base64图片，将base64图片上传
            delta.ops = delta.ops.filter((item: any) => {
                const { insert } = item;
                if(insert && typeof insert === 'object' && insert.image){
                    if(insert.image.indexOf('base64') !== -1){
                        requestFile(base64URLtoFile(insert.image)).then(
                            (url: any) => {
                                let quill = reactQuillRef.current.getEditor();//获取到编辑器本身
                                const cursorPosition = quill.getSelection().index;//获取当前光标位置
                                quill.insertEmbed(cursorPosition, "image", url);//插入图片
                                quill.setSelection(cursorPosition + 1);//光标位置加1
                            }
                        );
                        return false;
                    }
                }
                return true;
            })
            return delta;
        });
    }, []);


    const [modules, setModules] = useState(() => {
        return {
            clipboard:{},
            blotFormatter:{},
            toolbar: {
                container: [
                    [{ 'size': ['small', false, 'large', 'huge'] }], //字体设置
                    [{ 'header': [1, 2, 3, 4, 5, 6, false] }], //标题字号，不能设置单个字大小
                    ['bold', 'italic', 'underline', 'strike'],  
                    [{ 'list': 'ordered' }, { 'list': 'bullet' }, { 'indent': '-1' }, { 'indent': '+1' }],
                    ['link', 'image',], // a链接和图片的显示
                    [{ 'align': [] }],
                    [{
                    'background': ['rgb(  0,   0,   0)', 'rgb(230,   0,   0)', 'rgb(255, 153,   0)',
                        'rgb(255, 255,   0)', 'rgb(  0, 138,   0)', 'rgb(  0, 102, 204)',
                        'rgb(153,  51, 255)', 'rgb(255, 255, 255)', 'rgb(250, 204, 204)',
                        'rgb(255, 235, 204)', 'rgb(255, 255, 204)', 'rgb(204, 232, 204)',
                        'rgb(204, 224, 245)', 'rgb(235, 214, 255)', 'rgb(187, 187, 187)',
                        'rgb(240, 102, 102)', 'rgb(255, 194, 102)', 'rgb(255, 255, 102)',
                        'rgb(102, 185, 102)', 'rgb(102, 163, 224)', 'rgb(194, 133, 255)',
                        'rgb(136, 136, 136)', 'rgb(161,   0,   0)', 'rgb(178, 107,   0)',
                        'rgb(178, 178,   0)', 'rgb(  0,  97,   0)', 'rgb(  0,  71, 178)',
                        'rgb(107,  36, 178)', 'rgb( 68,  68,  68)', 'rgb( 92,   0,   0)',
                        'rgb(102,  61,   0)', 'rgb(102, 102,   0)', 'rgb(  0,  55,   0)',
                        'rgb(  0,  41, 102)', 'rgb( 61,  20,  10)', false]
                    }],
                    [{
                    'color': ['rgb(  0,   0,   0)', 'rgb(230,   0,   0)', 'rgb(255, 153,   0)',
                        'rgb(255, 255,   0)', 'rgb(  0, 138,   0)', 'rgb(  0, 102, 204)',
                        'rgb(153,  51, 255)', 'rgb(255, 255, 255)', 'rgb(250, 204, 204)',
                        'rgb(255, 235, 204)', 'rgb(255, 255, 204)', 'rgb(204, 232, 204)',
                        'rgb(204, 224, 245)', 'rgb(235, 214, 255)', 'rgb(187, 187, 187)',
                        'rgb(240, 102, 102)', 'rgb(255, 194, 102)', 'rgb(255, 255, 102)',
                        'rgb(102, 185, 102)', 'rgb(102, 163, 224)', 'rgb(194, 133, 255)',
                        'rgb(136, 136, 136)', 'rgb(161,   0,   0)', 'rgb(178, 107,   0)',
                        'rgb(178, 178,   0)', 'rgb(  0,  97,   0)', 'rgb(  0,  71, 178)',
                        'rgb(107,  36, 178)', 'rgb( 68,  68,  68)', 'rgb( 92,   0,   0)',
                        'rgb(102,  61,   0)', 'rgb(102, 102,   0)', 'rgb(  0,  55,   0)',
                        'rgb(  0,  41, 102)', 'rgb( 61,  20,  10)']
                    }],
                    ['clean'], //清空
                    // ['emoji'], //emoji表情，设置了才能显示
                   ['video'], 
                ],
                handlers: {
                    // 'image': imageHeader,
                    // 'video': () => {},
                },
            },
            // ImageExtend: {
            //   loading: true,
            //   name: 'img',
            //   action: RES_URL + "connector?isRelativePath=true",
            //   response: res => FILE_URL + res.info.url
            // },
            // ImageDrop: true,
            'emoji-toolbar': false,  //是否展示出来
            "emoji-textarea": false, //我不需要emoji展示在文本框所以设置为false
            "emoji-shortname": false, 
        }
    })
    
    return (
        <Spin delay={500} loading={loading} tip={`${file.name}`} className="w-full">
            <ReactQuill
                ref={reactQuillRef}
                modules={modules}
                className="react-quill-component"
                {...props}
                value={props.value || ''}
            />
        </Spin>
    )
}

export default EditorQuill;